/* keep: bitmask of retained fields, e.g. F_ID | F_NAME */
struct user_dto { int id; char name[64]; };

void project(const struct user *in, unsigned keep, struct user_dto *out) {
    memset(out, 0, sizeof *out);
    if (keep & F_ID)   out->id = in->id;
    if (keep & F_NAME) snprintf(out->name, sizeof out->name, "%s", in->name);
    /* F_SSN is never copied: the DTO has no member for it */
}
